css:
html .cl .terms { display: grid; grid-template-columns: 240px minmax(0, 1fr); gap: 32px; align-items: start; }
html .cl .toc { position: sticky; top: 110px; display: grid; gap: 2px; font-size: 13px; max-height: calc(100vh - 130px); overflow-y: auto; overscroll-behavior: contain; align-content: start; }
html .cl .toc a { color: var(--text-3); text-decoration: none; padding: 5px 10px; border-left: 2px solid var(--border); }
html .cl .toc a:hover { color: var(--green-text); border-left-color: var(--green); }
html .cl .toc b { font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: var(--text-3); margin: 0 0 8px; font-weight: 600; }
html .cl .legal-doc { display: grid; gap: 14px; min-width: 0; }
html .cl .legal-doc .panel { padding: clamp(20px, 3vw, 32px); }
html .cl .legal-doc .lead p { margin: 0 0 8px; color: var(--text); }
html .cl .legal-doc ol { margin: 0; padding: 0; list-style: none; counter-reset: t; display: grid; gap: 22px; }
html .cl .legal-doc ol > li { counter-increment: t; }
html .cl .legal-doc h3 { font-size: 22px; display: flex; gap: 12px; align-items: baseline; scroll-margin-top: 110px; }
html .cl .legal-doc h3::before { content: counter(t, decimal-leading-zero); font-size: 14px; color: #ff3d33; font-family: var(--head); letter-spacing: .06em; }
html .cl .legal-doc p { margin: 10px 0 0; max-width: 72ch; overflow-wrap: anywhere; }
html .cl .legal-doc ul { margin: 8px 0 0; padding-left: 20px; max-width: 72ch; display: grid; gap: 4px; }
html .cl .legal-doc ul li::marker { color: var(--green); }
html .cl .legal-doc a { color: var(--green-text); }
html .cl .plain-hero h1 { font-size: clamp(36px, 5.6vw, 72px); max-width: 20ch; }
@media (max-width: 900px) {html .cl .terms { grid-template-columns: minmax(0, 1fr); }
html .cl .toc { display: none; }
 }
